import{_ as e,a as n,c as s,ac as l}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"Codex Token 利用","description":"通过任务边界、上下文控制与验证减少 Token 浪费","frontmatter":{"title":"Codex Token 利用","description":"通过任务边界、上下文控制与验证减少 Token 浪费","sources":[{"repository":"TeamDocs","file":"docs/engineering/codex/Token-Usage.md"}],"showdocs":{"topics":[{"id":"ai","title":"AI 与 Codex","link":"/topics/ai/"},{"id":"engineering","title":"编辑器与 IDE","link":"/topics/engineering/"}],"kind":"AI与Codex完整实践与解答","scope":"historical","audience":"general","group":"工程与工具","summary":"通过任务边界、上下文控制与验证减少 Token 浪费","status":"active","related":[{"title":"全局 AGENTS.md","link":"/tools/ai/guide/global-agents","kind":"AI与Codex上手与对象","scope":"general","audience":"general"},{"title":"AI辅助开发的任务、上下文与验收","link":"/tools/ai/assisted-development-workflow","kind":"AI与Codex上手与对象","scope":"general","audience":"general"},{"title":"Codex 插件用途与选择记录","link":"/tools/ai/reference/plugin","kind":"AI与Codex任务与配置","scope":"historical","audience":"general"},{"title":"Codex 模型对比与选择","link":"/tools/ai/reference/model-selection","kind":"AI与Codex任务与配置","scope":"historical","audience":"general"},{"title":"Codex Token 计算规则","link":"/tools/ai/reference/token-calculation","kind":"AI与Codex任务与配置","scope":"historical","audience":"general"}],"prev":false,"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":false},"headers":[],"relativePath":"tools/ai/practice/token-usage.md","filePath":"tools/ai/practice/token-usage.md"}'),i={name:"tools/ai/practice/token-usage.md"};function t(p,a,o,r,d,c){return n(),s("div",null,[...a[0]||(a[0]=[l(`<h1 id="codex-token-利用-低消耗、高质量使用手册" tabindex="-1">Codex Token 利用：低消耗、高质量使用手册 <a class="header-anchor" href="#codex-token-利用-低消耗、高质量使用手册" aria-label="Permalink to &quot;Codex Token 利用：低消耗、高质量使用手册&quot;">​</a></h1><blockquote><p>历史范围：本文保留来源记录中的模型系列、费率示例和界面名称，未将其核验为当前可用配置。计量方法与任务组织原则可参考；实际模型和价格请以文末官方入口及账号界面为准。</p></blockquote><p>节省 Token 不是单纯缩短提示词，而是减少无效上下文、无边界搜索、超长工具输出和反复返工。</p><blockquote><p><strong>最低足够模型 × 最小必要上下文 × 最小工具集 × 明确验收标准 = 更低 Token + 更高一次成功率</strong></p></blockquote><h2 id="一、一页结论" tabindex="-1">一、一页结论 <a class="header-anchor" href="#一、一页结论" aria-label="Permalink to &quot;一、一页结论&quot;">​</a></h2><table tabindex="0"><thead><tr><th>需求</th><th>优先选择</th><th>应避免</th></tr></thead><tbody><tr><td>读取、修改和运行本地代码</td><td>Codex 内置文件、Shell、Git 和测试工具</td><td>粘贴整个仓库或优先接入 MCP</td></tr><tr><td>固定项目规范</td><td><code>AGENTS.md</code></td><td>每次重复粘贴规范</td></tr><tr><td>重复的标准流程</td><td>Skill</td><td>长期复制同一段提示词</td></tr><tr><td>可共享且带外部集成的流程</td><td>Plugin</td><td>安装所有可能用到的插件</td></tr><tr><td>外部实时数据或操作</td><td>MCP</td><td>拉取完整历史和无关字段</td></tr><tr><td>复杂、模糊或高风险任务</td><td>Plan Mode + 较强模型</td><td>未调查就大范围修改</td></tr><tr><td>可独立并行的调查</td><td>Subagents</td><td>为小任务启动多个代理</td></tr></tbody></table><p>推荐默认策略：</p><ul><li>日常开发使用 <strong>Terra + Medium</strong>。</li><li>清晰、机械、可重复任务使用 <strong>Luna + Low</strong>。</li><li>架构、疑难调试、大迁移和安全审查使用 <strong>Sol + High</strong>。</li><li>一个会话尽量只处理一个目标；主题明显变化时新开会话并附简短交接摘要。</li><li>本地问题先使用内置工具；只有信息在仓库外或需要外部动作时才使用 MCP 或插件。</li></ul><p>模型的详细区别参见：<a href="/tools/ai/reference/model-selection">模型对比 &amp; 模型选择</a>。</p><h2 id="二、token-浪费在哪里" tabindex="-1">二、Token 浪费在哪里 <a class="header-anchor" href="#二、token-浪费在哪里" aria-label="Permalink to &quot;二、Token 浪费在哪里&quot;">​</a></h2><p>一次 Codex 任务的消耗主要来自：</p><ol><li><strong>固定上下文</strong>：系统指令、<code>AGENTS.md</code>、Skill 简介和工具定义。</li><li><strong>任务上下文</strong>：提示词、附件、选中代码和粘贴日志。</li><li><strong>工具回传</strong>：搜索结果、命令输出、测试日志和 MCP 数据。</li><li><strong>模型输出与推理</strong>：计划、解释、代码和最终总结。</li><li><strong>返工与并行</strong>：重复读取、多轮纠错和子代理的独立调用。</li></ol><p>最常见的浪费包括：</p><ul><li>要求读取整个仓库，而不是从路径、符号或失败测试开始定位。</li><li>直接粘贴整份日志，真正相关的却只有几行。</li><li>所有任务都使用最强模型和最高推理等级。</li><li>同时启用大量插件、MCP 工具或子代理。</li><li>没有给出范围、约束和完成条件，导致模型反复猜测。</li><li>无关任务持续堆在同一个长会话中。</li><li>最终只需要补丁，却要求长篇背景解释。</li></ul><p>优化优先级通常是：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>减少返工 &gt; 限制工具输出 &gt; 缩小读取范围 &gt; 选择合适模型 &gt; 缩短最终回答</span></span></code></pre></div><h2 id="三、使用任务契约代替长提示词" tabindex="-1">三、使用任务契约代替长提示词 <a class="header-anchor" href="#三、使用任务契约代替长提示词" aria-label="Permalink to &quot;三、使用任务契约代替长提示词&quot;">​</a></h2><p>高质量任务至少应包含 <strong>目标、上下文、范围、约束和完成条件</strong>。</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>【目标】</span></span>
<span class="line"><span>要解决什么问题，最终产生什么结果。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【上下文】</span></span>
<span class="line"><span>相关文件、目录、错误、Issue 或已知事实。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【范围】</span></span>
<span class="line"><span>允许读取和修改的路径；明确排除哪些内容。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【约束】</span></span>
<span class="line"><span>架构、安全、兼容性、依赖和编码规范。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【工具策略】</span></span>
<span class="line"><span>优先使用哪些工具；哪些工具不要使用。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【执行方式】</span></span>
<span class="line"><span>直接实施还是先调查和计划；是否允许子代理。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【完成条件】</span></span>
<span class="line"><span>需要通过哪些测试、Lint、类型检查和行为验证。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【输出格式】</span></span>
<span class="line"><span>限定最终需要的改动、证据、风险和篇幅。</span></span></code></pre></div><h3 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h3><p>低质量任务：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我优化登录功能，顺便修复问题。</span></span></code></pre></div><p>更有效的任务：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>【目标】</span></span>
<span class="line"><span>修复 Access Token 过期后登录接口偶发返回 500 的问题。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【上下文】</span></span>
<span class="line"><span>错误入口为 internal/auth/refresh.go，相关测试在 internal/auth/refresh_test.go。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【范围】</span></span>
<span class="line"><span>只修改 internal/auth/；不修改数据库结构和公共协议。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【约束】</span></span>
<span class="line"><span>保持 Go 1.23 兼容，不增加依赖，使用最小 diff。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【工具策略】</span></span>
<span class="line"><span>先用 rg 定位错误处理链，第一轮最多读取 5 个文件；不要联网或调用 MCP。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【完成条件】</span></span>
<span class="line"><span>过期 Token 返回 401，其他异常仍返回 500；相关测试、go test 和 lint 通过。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【输出格式】</span></span>
<span class="line"><span>只报告修改文件、根因、验证结果和剩余风险。</span></span></code></pre></div><h2 id="四、上下文控制-先定位-再读取" tabindex="-1">四、上下文控制：先定位，再读取 <a class="header-anchor" href="#四、上下文控制-先定位-再读取" aria-label="Permalink to &quot;四、上下文控制：先定位，再读取&quot;">​</a></h2><p>本地代码任务推荐按以下顺序执行：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>精确搜索 → 读取少量相关文件 → 最小修改</span></span>
<span class="line"><span>→ 针对性测试 → 完整验证 → Review 最终 Diff</span></span></code></pre></div><p>可以在任务中直接加入：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>先使用文件名、符号名和 rg 定位最相关文件。</span></span>
<span class="line"><span>第一轮最多读取 5 个文件，不扫描 node_modules、dist、vendor、生成目录和大日志。</span></span>
<span class="line"><span>需要扩大范围时，先说明证据和原因。</span></span></code></pre></div><p>其他实用规则：</p><ul><li>提供入口文件、错误堆栈中的首个业务位置或失败测试名称。</li><li>使用 <code>git diff -- &lt;path&gt;</code>，避免无差别读取所有变更。</li><li>在大型仓库中明确允许和禁止访问的目录。</li><li>稳定结论用简短摘要记录，避免重复读取同一批资料。</li><li>新主题使用新会话，只携带必要的交接结论。</li></ul><h2 id="五、限制工具输出" tabindex="-1">五、限制工具输出 <a class="header-anchor" href="#五、限制工具输出" aria-label="Permalink to &quot;五、限制工具输出&quot;">​</a></h2><p>工具输出往往比提示词更容易占满上下文。</p><h3 id="shell-和测试" tabindex="-1">Shell 和测试 <a class="header-anchor" href="#shell-和测试" aria-label="Permalink to &quot;Shell 和测试&quot;">​</a></h3><ul><li>第一轮运行针对性测试，通过后再扩大验证范围。</li><li>使用 <code>rg</code>、<code>git diff --stat</code> 和限定路径的 diff。</li><li>长日志只保留失败摘要、首个根因、相关堆栈和退出码。</li><li>超长输出先写入日志文件，再搜索关键模式，不要全部回传到对话。</li></ul><p>可复制指令：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>命令输出超过 200 行时不要完整回传；</span></span>
<span class="line"><span>只保留失败摘要、首个根因、必要堆栈和命令退出码。</span></span></code></pre></div><h3 id="web-search" tabindex="-1">Web Search <a class="header-anchor" href="#web-search" aria-label="Permalink to &quot;Web Search&quot;">​</a></h3><ul><li>纯本地仓库任务关闭搜索。</li><li>一般外部资料优先使用缓存或已索引结果。</li><li>当前版本、近期发布和实时信息才使用在线搜索。</li><li>已经存在于仓库文档中的内容，不要重复联网查找。</li></ul><h3 id="最终回答" tabindex="-1">最终回答 <a class="header-anchor" href="#最终回答" aria-label="Permalink to &quot;最终回答&quot;">​</a></h3><p>最终输出通常只需要：</p><ul><li>修改了哪些文件。</li><li>根因或关键设计决策。</li><li>执行了哪些验证及结果。</li><li>剩余风险和未解决事项。</li></ul><h2 id="六、把长期信息放在正确位置" tabindex="-1">六、把长期信息放在正确位置 <a class="header-anchor" href="#六、把长期信息放在正确位置" aria-label="Permalink to &quot;六、把长期信息放在正确位置&quot;">​</a></h2><h3 id="agents-md-稳定项目规则" tabindex="-1"><code>AGENTS.md</code>：稳定项目规则 <a class="header-anchor" href="#agents-md-稳定项目规则" aria-label="Permalink to &quot;\`AGENTS.md\`：稳定项目规则&quot;">​</a></h3><p>适合保存：</p><ul><li>仓库结构和关键目录。</li><li>构建、测试、Lint 和类型检查命令。</li><li>架构约束、编码规范和禁止事项。</li><li>Code Review 标准和完成定义。</li></ul><p><code>AGENTS.md</code> 应短、准、可执行。根目录保存通用规则，子目录只补充局部差异。不要写长篇背景和模糊口号。</p><h3 id="skill-重复操作流程" tabindex="-1">Skill：重复操作流程 <a class="header-anchor" href="#skill-重复操作流程" aria-label="Permalink to &quot;Skill：重复操作流程&quot;">​</a></h3><p>适合封装 PR 检查、日志诊断、发布说明、数据库迁移规划等重复流程。Skill 按需加载，比把所有流程长期塞进 <code>AGENTS.md</code> 更节省上下文。</p><h3 id="plugin-团队共享的能力组合" tabindex="-1">Plugin：团队共享的能力组合 <a class="header-anchor" href="#plugin-团队共享的能力组合" aria-label="Permalink to &quot;Plugin：团队共享的能力组合&quot;">​</a></h3><p>适合分发 Skill、外部应用、MCP 和标准工作流。只安装确实需要的插件，当前任务只启用相关能力。</p><h3 id="mcp-外部实时上下文" tabindex="-1">MCP：外部实时上下文 <a class="header-anchor" href="#mcp-外部实时上下文" aria-label="Permalink to &quot;MCP：外部实时上下文&quot;">​</a></h3><p>仅在信息不在仓库、数据经常变化或需要执行外部动作时使用。调用时限制服务器、工具、字段、日期范围和返回数量。</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>使用 GitHub MCP 读取指定仓库的 Issue #842：</span></span>
<span class="line"><span>- 只读取标题、正文、标签和最近 10 条评论；</span></span>
<span class="line"><span>- 不读取其他 Issue，不调用写工具；</span></span>
<span class="line"><span>- 返回结构化摘要，不返回完整历史；</span></span>
<span class="line"><span>- 再结合本地指定目录分析根因。</span></span></code></pre></div><h2 id="七、plan-mode-和-subagents" tabindex="-1">七、Plan Mode 和 Subagents <a class="header-anchor" href="#七、plan-mode-和-subagents" aria-label="Permalink to &quot;七、Plan Mode 和 Subagents&quot;">​</a></h2><h3 id="什么时候使用-plan-mode" tabindex="-1">什么时候使用 Plan Mode <a class="header-anchor" href="#什么时候使用-plan-mode" aria-label="Permalink to &quot;什么时候使用 Plan Mode&quot;">​</a></h3><p>适合：</p><ul><li>需求模糊或有多个合理方案。</li><li>改动跨模块、跨服务。</li><li>需要迁移、兼容或回滚设计。</li><li>错误成本高。</li></ul><p>明确的小函数修改、指定测试或机械转换可以直接执行，无需为规划额外消耗 Token。</p><h3 id="subagents-不是省-token-工具" tabindex="-1">Subagents 不是省 Token 工具 <a class="header-anchor" href="#subagents-不是省-token-工具" aria-label="Permalink to &quot;Subagents 不是省 Token 工具&quot;">​</a></h3><p>子代理能减少主会话的上下文污染，但每个代理都会独立调用模型和工具，总消耗通常更高。</p><p>只在多个任务可以独立并行时使用，例如分别分析代码、测试和日志。避免多个代理同时修改同一批文件。</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>每个子代理只负责一个明确的只读范围，不修改代码，</span></span>
<span class="line"><span>最多返回 8 条结论和必要证据；</span></span>
<span class="line"><span>主代理汇总、去重并验证后再决定是否实施。</span></span></code></pre></div><h2 id="八、三套标准工作流" tabindex="-1">八、三套标准工作流 <a class="header-anchor" href="#八、三套标准工作流" aria-label="Permalink to &quot;八、三套标准工作流&quot;">​</a></h2><h3 id="简单、明确任务" tabindex="-1">简单、明确任务 <a class="header-anchor" href="#简单、明确任务" aria-label="Permalink to &quot;简单、明确任务&quot;">​</a></h3><ol><li>Luna + Low。</li><li>指定文件、符号和完成条件。</li><li>不使用 Plan Mode、MCP 和子代理。</li><li>运行一个针对性验证。</li><li>最终只输出改动、测试和风险。</li></ol><h3 id="常规工程任务" tabindex="-1">常规工程任务 <a class="header-anchor" href="#常规工程任务" aria-label="Permalink to &quot;常规工程任务&quot;">​</a></h3><ol><li>Terra + Medium。</li><li>先搜索定位，第一轮读取少量文件。</li><li>采用最小 diff。</li><li>针对性测试通过后再运行更广验证。</li><li>Review 最终 Diff。</li></ol><h3 id="复杂、高风险任务" tabindex="-1">复杂、高风险任务 <a class="header-anchor" href="#复杂、高风险任务" aria-label="Permalink to &quot;复杂、高风险任务&quot;">​</a></h3><ol><li>Sol + High。</li><li>使用 Plan Mode 明确假设、方案和回滚策略。</li><li>MCP 只接入必要的外部系统。</li><li>子代理只承担独立、只读调查。</li><li>分阶段实现，每阶段独立验证。</li><li>最终复核 Diff、风险和证据。</li></ol><h2 id="九、可复制的-token-纪律" tabindex="-1">九、可复制的 Token 纪律 <a class="header-anchor" href="#九、可复制的-token-纪律" aria-label="Permalink to &quot;九、可复制的 Token 纪律&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Token discipline:</span></span>
<span class="line"><span>- Use the smallest sufficient model and reasoning level.</span></span>
<span class="line"><span>- Inspect before editing; start from exact paths, symbols, or failing tests.</span></span>
<span class="line"><span>- Do not scan generated directories or the entire repository without evidence.</span></span>
<span class="line"><span>- Read at most 5 relevant files in the first pass; explain before expanding scope.</span></span>
<span class="line"><span>- Prefer rg, targeted tests, and focused git diff commands.</span></span>
<span class="line"><span>- Do not return full logs; return failing lines, root cause, exit code, and a concise summary.</span></span>
<span class="line"><span>- Do not use web search, plugins, MCP, or subagents unless they materially help.</span></span>
<span class="line"><span>- Keep the final answer concise: changed files, tests, risks, and unresolved items.</span></span></code></pre></div><h2 id="十、团队落地检查表" tabindex="-1">十、团队落地检查表 <a class="header-anchor" href="#十、团队落地检查表" aria-label="Permalink to &quot;十、团队落地检查表&quot;">​</a></h2><ul><li>[ ] 根目录有短而准确的 <code>AGENTS.md</code>。</li><li>[ ] 写明构建、测试、Lint 和完成标准。</li><li>[ ] 团队已确定默认模型与升级策略。</li><li>[ ] 重复流程已转成单一职责 Skill。</li><li>[ ] 插件和 MCP 使用最小权限及工具白名单。</li><li>[ ] 大日志有摘要或截断策略。</li><li>[ ] 复杂任务使用 Plan Mode，简单任务直接执行。</li><li>[ ] 子代理只用于收益明确的独立并行任务。</li><li>[ ] 最终输出固定包含改动、验证、风险和未解决事项。</li></ul><p>建议持续观察一次通过率、平均对话轮数、模型升级率、工具输出量和测试返工率。真正有效的 Token 优化，应同时降低平均消耗并提高首次验收成功率。</p><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><ul><li><a href="https://developers.openai.com/codex/models" target="_blank" rel="noopener noreferrer">Codex 模型</a></li><li><a href="https://developers.openai.com/codex/learn/best-practices" target="_blank" rel="noopener noreferrer">Codex 最佳实践</a></li><li><a href="https://developers.openai.com/codex/guides/agents-md" target="_blank" rel="noopener noreferrer">AGENTS.md 指南</a></li><li><a href="https://developers.openai.com/codex/plugins" target="_blank" rel="noopener noreferrer">Codex 插件</a></li><li><a href="https://developers.openai.com/codex/mcp" target="_blank" rel="noopener noreferrer">Model Context Protocol</a></li><li><a href="https://developers.openai.com/codex/subagents" target="_blank" rel="noopener noreferrer">Codex Subagents</a></li><li><a href="https://developers.openai.com/codex/config-reference" target="_blank" rel="noopener noreferrer">Codex 配置参考</a></li></ul>`,77)])])}const g=e(i,[["render",t]]);export{u as __pageData,g as default};
